package ru.mytabel.app.settings

// UI and export translations use a deterministic catalog; employer names and comments are never translated.
fun translate(text:String,language:String):String {
    if(language!="en")return text
    translations[text]?.let{return it}
    var result=text
    translations.entries.sortedByDescending{it.key.length}.filter{it.key.length>=4}.forEach{(ru,en)->result=result.replace(ru,en)}
    return result
}
